 5→import * as React from 'react';
 6→import { classNames as cx, type ComponentProps } from '../../../../util/componentUtil.ts';
 7→
 8→import cl from './Label.module.scss';
 9→
10→
11→export { cl as LabelClassNames };
12→
13→export type LabelPosition = 'inline-start' | 'inline-end';
14→
15→export type LabelProps = React.PropsWithChildren<ComponentProps<'label'> & {
16→  /** Whether this component should be unstyled. */
17→  unstyled?: undefined | boolean,
18→  
19→  /** The label text */
20→  label: React.ReactNode,
21→  
22→  /** The position of the label relative to the control. Default: 'inline-start'. */
23→  position?: undefined | LabelPosition,
24→}>;
25→/**
26→ * Wrapper around a control to add inline label text.
27→ */
28→export const Label = (props: LabelProps) => {
29→  const { unstyled = false, children, label, position = 'inline-start', ...propsRest } = props;
30→  
31→  return (
32→    // biome-ignore lint/a11y/noLabelWithoutControl: The control is nested inside the label.
33→    <label
34→      {...propsRest}
35→      className={cx(
36→        'bk',
37→        { [cl['bk-label']]: !unstyled },
38→        propsRest.className,
39→      )}
40→    >
41→      {position === 'inline-start' && <span className={cl['bk-label__text']}>{label}</span>}
42→      {children}
43→      {position === 'inline-end' && <span className={cl['bk-label__text']}>{label}</span>}
44→    </label>
45→  );
46→};
