 5→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
 6→
 7→import { H5 } from '../../../typography/Heading/Heading.tsx';
 8→import { Link as LinkDefault } from '../../actions/Link/Link.tsx';
 9→
10→import cl from './Card.module.scss';
11→
12→
13→export { cl as CardClassNames };
14→
15→
16→export type CardHeadingProps = ComponentProps<typeof H5> & {
17→  icon?: undefined | React.ReactElement,
18→};
19→export const CardHeading = ({ icon, ...propsRest }: CardHeadingProps) => {
20→  return (
21→    <H5 {...propsRest} className={cx(cl['bk-card__heading'], propsRest.className)}>
22→      {icon &&
23→        <>
24→          <span className={cx('_icon', cl['bk-card__heading__icon'])}>{icon}</span>
25→          <span className={cx('_content', cl['bk-card__heading__content'])}>{propsRest.children}</span>
26→        </>
27→      }
28→      {!icon && propsRest.children}
29→    </H5>
30→  );
31→};
32→
33→export type CardHeadingLinkProps = ComponentProps<typeof LinkDefault> & {
34→  icon?: undefined | React.ReactElement,
35→  Link?: undefined | typeof LinkDefault,
36→};
37→export const CardHeadingLink = ({ icon, Link = LinkDefault, ...propsRest }: CardHeadingLinkProps) => {
38→  return (
39→    <Link
40→      unstyled
41→      {...propsRest}
42→      className={cx(cl['bk-card__heading'], cl['bk-card__heading--link'], propsRest.className)}
43→    >
44→      {icon &&
45→        <>
46→          <span className={cx('_icon', cl['bk-card__heading__icon'])}>{icon}</span>
47→          <span className={cx('_content', cl['bk-card__heading__content'])}>{propsRest.children}</span>
48→        </>
49→      }
50→      {!icon && propsRest.children}
51→    </Link>
52→  );
53→};
54→
55→export type CardProps = ComponentProps<'section'> & {
56→  /** Whether this component should be unstyled. */
57→  unstyled?: undefined | boolean,
58→  
59→  /** If enabled, removes the outside border/padding. For use in nested contexts. Default: false. */
60→  flat?: undefined | boolean,
61→};
62→/**
63→ * Card component, a container similar to a panel but smaller and usually used in a list or grid.
64→ */
65→export const Card = Object.assign(
66→  (props: CardProps) => {
67→    const { children, unstyled = false, flat = false, ...propsRest } = props;
68→    
69→    return (
70→      <article
71→        {...propsRest}
72→        className={cx(
73→          'bk',
74→          { [cl['bk-card']]: !unstyled },
75→          { [cl['bk-card--flat']]: flat },
76→          propsRest.className,
77→        )}
78→      >
79→        {children}
80→      </article>
81→    );
82→  },
83→  {
84→    Heading: CardHeading,
85→    HeadingLink: CardHeadingLink,
86→  },
87→);
