51→export const isFileAccepted = (file: File, accept?: string) => {
52→  if (!accept) return true;
53→
54→  const acceptList = accept.split(',').map(type => type.trim());
55→
56→  return acceptList.some(acceptedType => {
57→    if (acceptedType.startsWith('.')) {
58→      return file.name.toLowerCase().endsWith(acceptedType.toLowerCase());
59→    }
60→    if (acceptedType.endsWith('/*')) {
61→      const baseType = acceptedType.replace('/*', '');
62→      return file.type.startsWith(baseType);
63→    }
64→    return file.type === acceptedType;
65→  });
