 12→
 13→
 14→export { cl as CheckboxGroupClassNames };
 15→
 16→export type CheckboxKey = string;
 17→
 18→export type CheckboxGroupContext = {
 19→  name?: undefined | CheckboxKey,
 20→  formId?: undefined | string,
 21→  selectedItems: undefined | Set<CheckboxKey>,
 22→  updateItem: (checkboxKey: CheckboxKey, checked: boolean) => void,
 23→};
 24→export const CheckboxGroupContext = React.createContext<null | CheckboxGroupContext>(null);
 25→export const useCheckboxGroupContext = () => {
 26→  const context = React.use(CheckboxGroupContext);
 27→  if (context === null) { throw new Error(`Missing CheckboxGroupContext provider`); }
 28→  return context;
 29→};
 30→
 31→export type CheckboxItemProps = React.ComponentProps<typeof Checkbox.Labeled> & {
 32→  /** The unique key of this checkbox within the checkbox group. */
 33→  checkboxKey: CheckboxKey,
 34→};
 35→export const CheckboxItem = ({ checkboxKey, ...propsRest }: CheckboxItemProps) => {
 36→  const context = useCheckboxGroupContext();
 37→  
 38→  const checked: undefined | boolean = typeof context.selectedItems === 'undefined'
 39→    ? undefined // Uncontrolled
 40→    : context.selectedItems.has(checkboxKey); // Controlled
 41→  
 42→  const onChange = React.useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
 43→    propsRest.onChange?.(event);
 44→    context.updateItem(checkboxKey, event.target.checked);
 45→  }, [propsRest.onChange, context.updateItem, checkboxKey]);
 46→  
 47→  return (
 48→    <Checkbox.Labeled
 49→      // Note: `<fieldset>` also has a `form` attribute, but just setting `form` on  `<fieldset>` does not affect any
 50→      // of the descendant `<input>` elements. See: https://developer.mozilla.org/en-US/docs/Web/HTML/Element/fieldset
 51→      form={context.formId}
 52→      name={context.name}
 53→      value={checkboxKey}
 54→      checked={checked}
 55→      onChange={typeof checked === 'undefined' ? undefined : onChange}
 56→      {...propsRest}
 57→    />
 58→  );
 59→};
 60→
 61→export type CheckboxGroupProps = ComponentProps<typeof FieldSet> & {
 62→  /** Whether this component should be unstyled. */
