16→export const handleWrongFileFormat = (fileName: string, fileType: string) => {
17→  let friendlyFileType = fileType.replace('/*', '');
18→  const fileTypeArray = fileType.split(',');
19→  if (fileTypeArray.length > 1) {
20→    const last = fileTypeArray.pop();
21→    friendlyFileType = `${fileTypeArray.join(', ')} or ${last}`;
22→  }
23→  notify.error(`The supplied file ${fileName} is not accepted, please provide a ${friendlyFileType} file.`);
24→};
