28→  handleFile: (result: string | ArrayBuffer | null, file: File, error?: undefined | unknown) => void,
29→  readAsArrayBuffer?: boolean,
30→  encoding = 'UTF-8',
31→) => {
32→  let result: string | ArrayBuffer | null = '';
33→
34→  try {
35→    const fileReader = new FileReader();
36→    if (!readAsArrayBuffer) {
37→      fileReader.readAsText(file, encoding);
38→    } else {
39→      fileReader.readAsArrayBuffer(file);
40→    }
41→    fileReader.onloadend = () => {
42→      result = fileReader.result;
43→      handleFile(result, file);
44→    };
45→  } catch (e: unknown) {
46→    console.error(e);
47→    handleFile(result, file, e);
48→  }
49→};
50→
51→export const isFileAccepted = (file: File, accept?: string) => {
52→  if (!accept) return true;
53→
54→  const acceptList = accept.split(',').map(type => type.trim());
55→
56→  return acceptList.some(acceptedType => {
57→    if (acceptedType.startsWith('.')) {
58→      return file.name.toLowerCase().endsWith(acceptedType.toLowerCase());
59→    }
60→    if (acceptedType.endsWith('/*')) {
61→      const baseType = acceptedType.replace('/*', '');
62→      return file.type.startsWith(baseType);
63→    }
64→    return file.type === acceptedType;
65→  });
66→};
