  4→
  5→import { classNames as cx, type ComponentProps } from '../../../../util/componentUtil.ts';
  6→import * as React from 'react';
  7→
  8→import { FieldSet } from '../../common/FieldSet/FieldSet.tsx';
  9→import { Checkbox } from '../Checkbox/Checkbox.tsx';
 10→
 11→import cl from './CheckboxGroup.module.scss';
 12→
 13→
 14→export { cl as CheckboxGroupClassNames };
 15→
 16→export type CheckboxKey = string;
 17→
 18→export type CheckboxGroupContext = {
 19→  name?: undefined | CheckboxKey,
 20→  formId?: undefined | string,
 21→  selectedItems: undefined | Set<CheckboxKey>,
 22→  updateItem: (checkboxKey: CheckboxKey, checked: boolean) => void,
 23→};
 24→export const CheckboxGroupContext = React.createContext<null | CheckboxGroupContext>(null);
 25→export const useCheckboxGroupContext = () => {
 26→  const context = React.use(CheckboxGroupContext);
 27→  if (context === null) { throw new Error(`Missing CheckboxGroupContext provider`); }
 28→  return context;
 29→};
 30→
 31→export type CheckboxItemProps = React.ComponentProps<typeof Checkbox.Labeled> & {
 32→  /** The unique key of this checkbox within the checkbox group. */
 33→  checkboxKey: CheckboxKey,
 34→};
 35→export const CheckboxItem = ({ checkboxKey, ...propsRest }: CheckboxItemProps) => {
 36→  const context = useCheckboxGroupContext();
 37→  
 38→  const checked: undefined | boolean = typeof context.selectedItems === 'undefined'
 39→    ? undefined // Uncontrolled
 40→    : context.selectedItems.has(checkboxKey); // Controlled
 41→  
 42→  const onChange = React.useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
 43→    propsRest.onChange?.(event);
 44→    context.updateItem(checkboxKey, event.target.checked);
 45→  }, [propsRest.onChange, context.updateItem, checkboxKey]);
 46→  
 47→  return (
 48→    <Checkbox.Labeled
 49→      // Note: `<fieldset>` also has a `form` attribute, but just setting `form` on  `<fieldset>` does not affect any
 50→      // of the descendant `<input>` elements. See: https://developer.mozilla.org/en-US/docs/Web/HTML/Element/fieldset
 51→      form={context.formId}
 52→      name={context.name}
 53→      value={checkboxKey}
 54→      checked={checked}
 55→      onChange={typeof checked === 'undefined' ? undefined : onChange}
 56→      {...propsRest}
 57→    />
 58→  );
 59→};
 60→
 61→export type CheckboxGroupProps = ComponentProps<typeof FieldSet> & {
 62→  /** Whether this component should be unstyled. */
 63→  unstyled?: undefined | boolean,
 64→  
 65→  /** The machine-readable name of the checkbox group, used for form data. */
 66→  name?: undefined | string,
 67→  
 68→  /** The human-readable label for the checkbox group. */
 69→  label?: undefined | React.ReactNode,
 70→  
 71→  /** The default checkboxes to select. Only relevant for uncontrolled usage (`selected` is `undefined`). */
 72→  defaultSelected?: undefined | Set<CheckboxKey>,
 73→  
 74→  /** The checkbox to select. If `undefined`, this component will be considered uncontrolled. */
 75→  selected?: undefined | Set<CheckboxKey>,
 76→  
 77→  /** Event handler which is called when the selected checkboxes changes. */
 78→  onUpdate?: undefined | ((checkboxKeys: Set<CheckboxKey>) => void),
 79→  
 80→  /** The orientation of the checkboxes, either vertical or horizontal. Default: 'horizontal'. */
 81→  orientation?: undefined | 'vertical' | 'horizontal',
 82→  
 83→  /** A class name to apply on the inner checkbox group (rather than the outer fieldset). */
 84→  contentClassName?: undefined | ComponentProps<typeof FieldSet>['contentClassName'],
 85→};
 86→
 87→/**
 88→ * A group of checkbox components.
 89→ */
 90→export const CheckboxGroup = Object.assign(
 91→  (props: CheckboxGroupProps) => {
 92→    const {
 93→      unstyled,
 94→      children,
 95→      form,
 96→      name,
 97→      label,
 98→      defaultSelected,
 99→      selected,
100→      onUpdate,
101→      orientation = 'horizontal',
102→      contentClassName,
103→      ...propsRest
104→    } = props;
105→    
106→    const [selectedItems, setSelectedItems] = React.useState<undefined | Set<CheckboxKey>>(selected ?? defaultSelected);
107→    
108→    const updateItem = React.useCallback((checkboxKey: CheckboxKey, checked: boolean) => {
109→      setSelectedItems(selectedItems => {
110→        const selectedItemsUpdated = new Set(selectedItems);
111→        
112→        if (checked) {
113→          selectedItemsUpdated.add(checkboxKey);
114→        } else {
115→          selectedItemsUpdated.delete(checkboxKey);
116→        }
117→        
118→        onUpdate?.(selectedItemsUpdated);
119→        return selectedItemsUpdated;
120→      });
121→    }, [onUpdate]);
122→    
123→    const context = React.useMemo<CheckboxGroupContext>(() => ({
124→      name,
125→      formId: form,
126→      selectedItems,
127→      updateItem,
128→    }), [name, form, selectedItems, updateItem]);
129→    
130→    return (
131→      <CheckboxGroupContext value={context}>
132→        <FieldSet
133→          legend={label}
134→          //role="group" // Note: already the default (and no other suitable `role` for checkbox group exists)
135→          {...propsRest}
136→          className={cx(
137→            'bk',
138→            cl['bk-checkbox-group'],
139→            { [cl['bk-checkbox-group--horizontal']]: orientation === 'horizontal' },
140→            { [cl['bk-checkbox-group--vertical']]: orientation === 'vertical' },
141→            propsRest.className,
142→          )}
143→          contentClassName={cx(cl['bk-checkbox-group__content'], contentClassName)}
144→        >
145→          {children}
146→        </FieldSet>
147→      </CheckboxGroupContext>
148→    );
149→  },
150→  {
151→    Checkbox: CheckboxItem,
152→  },
153→);
154→

